import {Button, Dialog, Stack} from '@primer/react'
import {settingsOrgSecurityConfigurationsNewPath} from '@github-ui/paths'
import {Link} from '@github-ui/react-core/link'
import {QuickSetupBody} from './QuickSetupDialog/QuickSetupBody'
import {useQuickSetupForm} from '../hooks/use-quick-setup-form'

export const DialogMode = {
  NEW: 'new',
  EDIT: 'edit',
} as const

export type DialogModeType = (typeof DialogMode)[keyof typeof DialogMode]

interface QuickSetupDialogProps {
  onClose: () => void
  org: string
  dialogMode: DialogModeType
}

export function QuickSetupDialog({onClose, org, dialogMode}: QuickSetupDialogProps) {
  const {formState, setFormState, handleSave} = useQuickSetupForm({
    org,
    onSuccess: onClose,
  })

  const getDialogTitle = () => {
    switch (dialogMode) {
      case DialogMode.EDIT:
        return 'Edit configuration'
      case DialogMode.NEW:
      default:
        return 'New configuration'
    }
  }

  const onSaveClick = async () => {
    if (dialogMode === DialogMode.NEW) {
      await handleSave()
    } else {
      // TODO: Handle edit case
      onClose()
    }
  }

  const renderBody = () => {
    return <QuickSetupBody formState={formState} onFormStateChange={setFormState} />
  }

  const customConfigLink = settingsOrgSecurityConfigurationsNewPath({org})

  const renderFooter = () => {
    return (
      <Stack direction="horizontal" padding="normal" justify="end" className="color-border-muted border-top">
        <Button as={Link} to={customConfigLink}>
          Custom Configuration
        </Button>
        <Button variant="primary" onClick={onSaveClick}>
          Save
        </Button>
      </Stack>
    )
  }

  return (
    <Dialog title={getDialogTitle()} onClose={onClose} renderFooter={renderFooter} data-testid="quick-setup-dialog">
      {renderBody()}
    </Dialog>
  )
}

try{ QuickSetupDialog.displayName ||= 'QuickSetupDialog' } catch {}