import {Button} from '@primer/react'
import {Link} from '@github-ui/react-router'

interface NewConfigurationButtonProps {
  link: string
  onOpenQuickSetup?: () => void
}

const NewConfigurationButton: React.FC<NewConfigurationButtonProps> = ({link, onOpenQuickSetup}) => {
  if (onOpenQuickSetup) {
    return (
      <Button data-testid="new-configuration" onClick={onOpenQuickSetup} variant="primary">
        New configuration
      </Button>
    )
  }

  return (
    <Button data-testid="new-configuration" as={Link} to={link} variant="primary">
      New configuration
    </Button>
  )
}

export default NewConfigurationButton

try{ NewConfigurationButton.displayName ||= 'NewConfigurationButton' } catch {}