import {useState, useCallback} from 'react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {settingsOrgQuickSetupSecurityConfigurationsCreatePath} from '@github-ui/paths'
import {SettingValue, QuickSetupApplyTo} from '../security-products-enablement-types'
import type {QuickSetupFormState, QuickSetupCreatePayload} from '../security-products-enablement-types'

export const getInitialFormState = (): QuickSetupFormState => ({
  secretProtection: SettingValue.Enabled,
  codeSecurity: SettingValue.Enabled,
  dependabot: SettingValue.Enabled,
  applyTo: QuickSetupApplyTo.All,
  enforced: false,
})

export const buildPayload = (formState: QuickSetupFormState): QuickSetupCreatePayload => {
  let repositoryIds: number[] | 'all'

  switch (formState.applyTo) {
    case QuickSetupApplyTo.All:
      repositoryIds = 'all'
      break
    case QuickSetupApplyTo.None:
    case QuickSetupApplyTo.Selected:
    default:
      repositoryIds = []
  }

  return {
    secret_protection: formState.secretProtection,
    code_security: formState.codeSecurity,
    dependabot: formState.dependabot,
    repository_ids: repositoryIds,
    enforced: formState.enforced,
  }
}

interface UseQuickSetupFormOptions {
  org: string
  onSuccess: () => void
}

export function useQuickSetupForm({org, onSuccess}: UseQuickSetupFormOptions) {
  const [formState, setFormState] = useState<QuickSetupFormState>(getInitialFormState)

  const handleSave = useCallback(async () => {
    const payload = buildPayload(formState)
    const url = settingsOrgQuickSetupSecurityConfigurationsCreatePath({org})

    await verifiedFetchJSON(url, {
      method: 'POST',
      body: payload,
    })

    onSuccess()
  }, [formState, org, onSuccess])

  return {
    formState,
    setFormState,
    handleSave,
  }
}
