import {Button, Link as PrimerLink, Stack} from '@primer/react'
import {Link} from '@github-ui/react-core/link'
import {useNavigate} from '@github-ui/use-navigate'
import {settingsOrgSecurityProductsPath, settingsOrgSecurityConfigurationsNewPath} from '@github-ui/paths'
import {useAppContext} from '../contexts/AppContext'
import Subhead from '../components/Subhead'
import {QuickSetupBody} from './QuickSetupDialog/QuickSetupBody'
import {useQuickSetupForm} from '../hooks/use-quick-setup-form'

import styles from './SecurityConfiguration.module.css'
import {clsx} from 'clsx'

export default function QuickSetupPage() {
  const {organization} = useAppContext()
  const navigate = useNavigate()

  const breadcrumbContextLink = settingsOrgSecurityProductsPath({org: organization})
  const customConfigLink = settingsOrgSecurityConfigurationsNewPath({org: organization})

  const {formState, setFormState, handleSave} = useQuickSetupForm({
    org: organization,
    onSuccess: () => navigate(breadcrumbContextLink),
  })

  return (
    <>
      <div className={styles.Box}>
        <PrimerLink as={Link} to={breadcrumbContextLink} className={styles.BreadcrumbLink}>
          Advanced Security
        </PrimerLink>
        {' / '}
        Set Up Advanced Security
      </div>
      <Subhead>
        <div className={styles.Box_1}>
          <h2 data-testid="quick-setup-title" className={clsx('h1-override-shared-component', styles.Text)}>
            Set Up Advanced Security
          </h2>
        </div>
      </Subhead>

      {/* Main content */}
      <div className="p-responsive">
        <div className="mb-2">Select what features you&apos;d like to enable:</div>
        <QuickSetupBody formState={formState} onFormStateChange={setFormState} />

        {/* Footer buttons */}
        <Stack direction="horizontal" className="mt-3">
          <Button variant="primary" onClick={handleSave}>
            Set up
          </Button>
          <Button as={Link} to={customConfigLink}>
            Custom Configuration
          </Button>
        </Stack>
      </div>
    </>
  )
}

try{ QuickSetupPage.displayName ||= 'QuickSetupPage' } catch {}