import {ActionMenu, ActionList, Link as PrimerLink, Stack, ToggleSwitch} from '@primer/react'
import {RepoIcon, ChecklistIcon} from '@primer/octicons-react'
import {useAppContext} from '../../contexts/AppContext'
import {SettingValue, QuickSetupApplyTo} from '../../security-products-enablement-types'
import type {QuickSetupFormState} from '../../security-products-enablement-types'

const SETTING_LABELS: Record<SettingValue, string> = {
  [SettingValue.Enabled]: 'Enabled',
  [SettingValue.Disabled]: 'Disabled',
  [SettingValue.NotSet]: 'Not set',
}

const APPLY_TO_LABELS: Record<QuickSetupApplyTo, string> = {
  [QuickSetupApplyTo.All]: 'All repositories',
  [QuickSetupApplyTo.Selected]: 'Selected repositories',
  [QuickSetupApplyTo.None]: 'None',
}

interface EnablementMenuProps {
  label: string
  selectedValue: SettingValue
  onSelect: (value: SettingValue) => void
}

function EnablementMenu({label, selectedValue, onSelect}: EnablementMenuProps) {
  const settingValues = Object.keys(SETTING_LABELS) as SettingValue[]

  return (
    <ActionMenu>
      <ActionMenu.Button>{SETTING_LABELS[selectedValue]}</ActionMenu.Button>
      <ActionMenu.Overlay>
        <ActionList selectionVariant="single" aria-label={label}>
          {settingValues.map(value => (
            <ActionList.Item
              key={value}
              selected={value === selectedValue}
              aria-checked={value === selectedValue}
              onSelect={() => onSelect(value)}
            >
              {SETTING_LABELS[value]}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

function getApplyToIcon(applyTo: QuickSetupApplyTo) {
  if (applyTo === QuickSetupApplyTo.All) return <RepoIcon size={16} />
  if (applyTo === QuickSetupApplyTo.Selected) return <ChecklistIcon size={16} />
  return null
}

interface QuickSetupBodyProps {
  formState: QuickSetupFormState
  onFormStateChange: (newState: QuickSetupFormState) => void
}

export function QuickSetupBody({formState, onFormStateChange}: QuickSetupBodyProps) {
  const {docsUrls} = useAppContext()

  const updateField = (updates: Partial<QuickSetupFormState>) => {
    onFormStateChange({...formState, ...updates})
  }

  return (
    <Stack gap="normal">
      {/* First bordered section - Security features */}
      <div className="color-border-muted border rounded-2 p-3">
        <Stack direction="vertical" gap="none">
          <Stack direction="horizontal" align="start" className="pb-3 color-border-muted border-bottom">
            <Stack direction="vertical" className="flex-1">
              <div className="text-bold">Secret Protection</div>
              <div className="color-fg-muted text-small">
                Receive alerts for and block secret leaks, validate secrets and scan with AI
              </div>
            </Stack>
            <EnablementMenu
              label="Secret Protection"
              selectedValue={formState.secretProtection}
              onSelect={value => updateField({secretProtection: value})}
            />
          </Stack>

          <Stack direction="horizontal" align="start" className="py-3 color-border-muted border-bottom">
            <Stack direction="vertical" className="flex-1">
              <div className="text-bold">Code Security</div>
              <div className="color-fg-muted text-small">
                Receive alerts for vulnerabilities, coding errors, and advanced dependency management
              </div>
            </Stack>
            <EnablementMenu
              label="Code Security"
              selectedValue={formState.codeSecurity}
              onSelect={value => updateField({codeSecurity: value})}
            />
          </Stack>

          <Stack direction="horizontal" align="start" className="pt-3">
            <Stack direction="vertical" className="flex-1">
              <div className="text-bold">Dependabot</div>
              <div className="color-fg-muted text-small">
                Receive alerts for vulnerable dependencies with automated update pull requests
              </div>
            </Stack>
            <EnablementMenu
              label="Dependabot"
              selectedValue={formState.dependabot}
              onSelect={value => updateField({dependabot: value})}
            />
          </Stack>
        </Stack>
      </div>

      {/* Second bordered section - Apply settings */}
      <Stack direction="vertical" gap="normal" className="color-border-muted border rounded-2 p-3">
        <Stack
          direction="horizontal"
          justify="space-between"
          align="center"
          className="pb-3 color-border-muted border-bottom"
        >
          <div className="text-bold">Apply to</div>
          <ActionMenu>
            <ActionMenu.Button>
              {getApplyToIcon(formState.applyTo)} {APPLY_TO_LABELS[formState.applyTo]}
            </ActionMenu.Button>
            <ActionMenu.Overlay>
              <ActionList selectionVariant="single" aria-label="Apply to">
                {(Object.keys(APPLY_TO_LABELS) as QuickSetupApplyTo[]).map(value => (
                  <ActionList.Item
                    key={value}
                    selected={value === formState.applyTo}
                    aria-checked={value === formState.applyTo}
                    onSelect={() => updateField({applyTo: value})}
                  >
                    {APPLY_TO_LABELS[value]}
                  </ActionList.Item>
                ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </Stack>

        <Stack direction="horizontal" justify="space-between" align="center">
          <div id="allow-repo-owners-label" className="text-bold">
            Allow repository owners to modify features
          </div>
          <ToggleSwitch
            aria-labelledby="allow-repo-owners-label"
            checked={!formState.enforced}
            onClick={() => updateField({enforced: !formState.enforced})}
          />
        </Stack>
      </Stack>

      {/* Cost information section */}
      <Stack direction="vertical">
        <div className="bgColor-muted rounded-2 p-3 text-small">
          <span>0 additional Secret Protection licenses </span>
          <span className="fgColor-muted">($19/active committer in private repositories)</span>
          <br />
          <span>100 additional Code Security licenses </span>
          <span className="fgColor-muted">($30/active committer in private repositories)</span>
          <br />
          <span>Dependabot is free for all repositories</span>
        </div>
        <div className="color-fg-muted text-small">
          Standard bill rate may not apply.{' '}
          <PrimerLink href={docsUrls.ghasBilling} target="_blank" rel="noopener noreferrer" inline>
            Learn more about billing
          </PrimerLink>
          .
        </div>
      </Stack>
    </Stack>
  )
}

try{ EnablementMenu.displayName ||= 'EnablementMenu' } catch {}
try{ QuickSetupBody.displayName ||= 'QuickSetupBody' } catch {}